import 'package:dio/dio.dart';import '../../../core/network/api_client.dart';import '../../../shared/models/vehicle_listing.dart';
class ListingRepository {ListingRepository(this.api);final ApiClient api;Future<List<VehicleListing>> nearby({required double latitude,required double longitude,double radius=25,String? category,String? type,bool available=false})async{final r=await api.dio.get('/listings/nearby',queryParameters:{'latitude':latitude,'longitude':longitude,'radiusKm':radius,'category':category,'listingType':type,'availableNow':available?'true':null});return (r.data['data'] as List).map((x)=>VehicleListing.fromJson(x)).toList();}Future<VehicleListing> detail(String id)async=>VehicleListing.fromJson((await api.dio.get('/listings/$id')).data['data']);Future<void> event(String id,String type)async{try{await api.dio.post('/listings/$id/events',data:{'eventType':type});}on DioException{/* Contact actions must not be blocked by analytics. */}}}
